<?php require __DIR__.'/app/layout.php';must_admin();
$tab=(string)($_GET['status']??'');$sql='SELECT r.*,s.name AS room_name,u.name AS organizer FROM reservations r JOIN rooms s ON s.id=r.room_id JOIN users u ON u.id=r.user_id WHERE 1=1';$params=[];
if(in_array($tab,['approved','pending','cancelled','rejected'],true)){$sql.=' AND r.status=?';$params[]=$tab;}
if(!empty($_GET['date']) && valid_date((string)$_GET['date'])){$sql.=' AND r.booking_date=?';$params[]=$_GET['date'];}
if((int)($_GET['room_id']??0)>0){$sql.=' AND r.room_id=?';$params[]=(int)$_GET['room_id'];}
if((int)($_GET['user_id']??0)>0){$sql.=' AND r.user_id=?';$params[]=(int)$_GET['user_id'];}
$q=trim((string)($_GET['q']??''));if($q!==''){$sql.=' AND (r.title LIKE ? OR u.name LIKE ?)';array_push($params,"%$q%","%$q%");}
$rows=all_rows($sql.' ORDER BY r.booking_date DESC,r.start_time DESC LIMIT 500',$params);
$rooms=all_rows('SELECT id,name FROM rooms ORDER BY name');$users=all_rows('SELECT id,name FROM users ORDER BY name');
page_start('Toutes les réservations','reservations');titlebar('Administration','Toutes les réservations','Validation des demandes et suivi global.'); ?>
<form class="filterbar" method="get"><input class="form-control flex-grow-1" name="q" value="<?=h($q)?>" placeholder="Rechercher une réunion ou organisateur"><input type="date" class="form-control" name="date" value="<?=h($_GET['date']??'')?>"><select name="status" class="form-select"><option value="">Tous statuts</option><?php foreach(['approved','pending','cancelled','rejected'] as $s):?><option value="<?=h($s)?>" <?= $tab===$s?'selected':''?>><?=h(status_text($s))?></option><?php endforeach;?></select><select class="form-select" name="room_id"><option value="">Toutes salles</option><?php foreach($rooms as $room):?><option value="<?=h($room['id'])?>" <?=(int)($_GET['room_id']??0)===(int)$room['id']?'selected':''?>><?=h($room['name'])?></option><?php endforeach;?></select><select class="form-select" name="user_id"><option value="">Tous utilisateurs</option><?php foreach($users as $u):?><option value="<?=h($u['id'])?>" <?=(int)($_GET['user_id']??0)===(int)$u['id']?'selected':''?>><?=h($u['name'])?></option><?php endforeach;?></select><button class="btn btn-primary">Filtrer</button></form>
<div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Objet</th><th>Organisateur</th><th>Salle</th><th>Date</th><th>Horaire</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold"><?=h($r['title'])?></td><td><?=h($r['organizer'])?></td><td><?=h($r['room_name'])?></td><td><?=h($r['booking_date'])?></td><td><?=h(substr($r['start_time'],0,5).' – '.substr($r['end_time'],0,5))?></td><td><?=pill($r['status'])?></td><td><div class="d-flex flex-wrap gap-1"><?php if($r['status']==='pending'):?><form action="<?=h(url('actions.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="reservation_review"><input type="hidden" name="decision" value="approved"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-sm btn-outline-success" title="Approuver"><i class="bi bi-check-lg"></i></button></form><form action="<?=h(url('actions.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="reservation_review"><input type="hidden" name="decision" value="rejected"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-sm btn-outline-danger" title="Refuser"><i class="bi bi-x-lg"></i></button></form><?php endif;?><?php if(can_change($r)):?><a class="btn btn-sm btn-outline-primary" href="<?=h(url('reservation.php?id='.$r['id']))?>" title="Modifier"><i class="bi bi-pencil"></i></a><form method="post" action="<?=h(url('actions.php'))?>" data-confirm="Annuler cette réservation ?"><?=csrf_field()?><input type="hidden" name="action" value="reservation_cancel"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-sm btn-outline-danger" title="Annuler"><i class="bi bi-x-circle"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty-state">Aucune réservation à afficher.</td></tr><?php endif;?></tbody></table></div><p class="small muted mb-0">Affichage limité aux 500 résultats les plus récents. Utilisez les filtres pour affiner.</p></div>
<?php page_end();?>
